WITH recent_shipments AS (SELECT * FROM shipments WHERE carrier IN ('Kerry', 'FedEx', 'DHL') OR delivered_date BETWEEN '2023-08-01' AND '2025-02-01'), shipments_stats AS (SELECT YEAR(delivered_date) AS delivered_year, CASE WHEN status IN ('DELIVERED', 'IN_TRANSIT') THEN 'core' ELSE 'other' END AS status_group, MIN(delivered_date) AS first_delivered_date FROM recent_shipments GROUP BY YEAR(delivered_date), CASE WHEN status IN ('DELIVERED', 'IN_TRANSIT') THEN 'core' ELSE 'other' END) SELECT delivered_year, status_group FROM shipments_stats
